Rules.InvariantScript:
// scr_Projects.OnVisible
// Purpose: initialize mode/selection state, then load Projects
// scoped to the current user's Directorate, and populate the
// reference collections the form dropdowns depend on.

Set(varMode, "View");
Set(varProjectSearchTerm, "");
Set(varProjectFilterDirectorate, "All");
Set(varProjectFilterProgramme, "All");
Set(varProjectFilterStatus, "All");
Set(varDirFilterResetKey, 0);

// Scoped Projects list
ClearCollect(
    colProjectsInScope,
    Filter(
        Projects,
        varCanViewAllReports
        || Directorate.Value = varUserDirectorateID
        || Directorate.Value = varUserDirectorate
    )
);

Set(varSelectedProject, If(CountRows(colProjectsInScope) > 0, First(colProjectsInScope), Blank()));

// Reference collections for the form dropdowns (previously missing)
ClearCollect(colProgrammes, Programmes);
ClearCollect(colDirectorates, Directorates);

// Filter bar dropdown collections
ClearCollect(colProgrammesFilter, {Title: "All", ProgrammeCode: "All"});
Collect(colProgrammesFilter, Filter(Programmes, Active = true));

ClearCollect(colStatusFilter, {Value: "All"});
Collect(colStatusFilter, Choices(Projects.Status));

