ControlPropertyState.AutoRuleBindingString:
// ============================================================
// scr_Project.OnVisible
// Purpose: initialize mode/selection state, then load Projects
// scoped to the current user's Directorate/Programme, matching
// both the short-code (DirectorateID) and full-name formats
// that exist across the schema.
// ============================================================
Set(varMode, "View");
Set(varProjectSearchTerm, "");
Set(varProjectFilterDirectorate, "All");
Set(varProjectFilterProgramme, "All");
Set(varProjectFilterStatus, "All");

ClearCollect(
    colProjectsInScope,
    Filter(
        Projects,
        varCanViewAllReports
            || Directorate.Value = varUserDirectorateID
            || Directorate.Value = varUserDirectorate
    )
);

Set(varSelectedProject, First(colProjectsInScope));

// In scr_Projects.OnVisible, replace direct ClearCollect(colProgrammes,...) with:
ClearCollect(colProgrammesFilter, {Title: "All", ProgrammeCode: "All"});
Collect(colProgrammesFilter, ShowColumns(Programmes, "Title", "ProgrammeCode"));

